def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timedelta, timezone

    seconds = nanoseconds // 1_000_000_000
    microseconds = nanoseconds % 1_000_000_000

    if tz is None:
        return datetime.fromtimestamp(seconds, timezone.utc) + timedelta(microseconds=microseconds)
    else:
        return tz.localize(datetime.fromtimestamp(seconds, timezone.utc) + timedelta(microseconds=microseconds))
