def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self.items.index(key)
    except ValueError:
        return -1

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """

    if not keys:
        return list(self.values())

    values = []
    for key in keys:
        if isinstance(key, int) and 0 <= key < len(self):
            values.append(self[key])
        elif key in self:
            values.append(self[key])
        else:
            raise KeyError(f"Key '{key}' not found in record")

    return values

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        keys = self.keys()
    for key in keys:
        try:
            if isinstance(key, int):
                result[self.keys()[key]] = self.values()[key]
            else:
                result[key] = self[key]
        except IndexError:
            raise IndexError(f"Index {key} is out of bounds for this record.")
        except KeyError:
            result[key] = None
    return result

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding half to even (also known as "bankers' rounding").

    :param n: The number to round
    :return: The rounded integer
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    if n >= 0:
        return int(n + 0.5) - int(n + 0.5) % 2
    else:
        return int(n - 0.5) - int(n - 0.5) % 2

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point:
        def __init__(self, **kwargs):
            for key, value in kwargs.items():
                if key in fields:
                    setattr(self, key, value)
                else:
                    raise ValueError(f"Invalid field: {key}")

        def get_srid(self):
            for field, srid in srid_map.items():
                if field in self.__dict__:
                    return srid
            return None

    return Point

