import functools
import hashlib
import threading

def hashkey(args,kwargs):
    """Default hash key function for the `cached` decorator."""
    return hashlib.sha256(str(args) + str(kwargs)).hexdigest()

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    if lock is None:
        lock = threading.Lock()

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            cache_key = key(args, kwargs)
            if cache_key not in cache:
                with lock:
                    if cache_key not in cache:  # double check
                        cache[cache_key] = func(*args, **kwargs)
            return cache[cache_key]
        return wrapper
    return decorator
