def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorating_function(user_function):
        return _TtlCacheWrapper(user_function, maxsize, ttl, timer, typed)
    return decorating_function

class _TtlCacheWrapper:
    def __init__(self, user_function, maxsize, ttl, timer, typed):
        self._user_function = user_function
        self._maxsize = maxsize
        self._ttl = ttl
        self._timer = timer
        self._typed = typed

        self.cache = {}
        self.expire_times = {}
        self.lock = Lock()
        self._last_update_timestamp = None

    def __call__(self, *args, **kwds):
        key = (args, frozenset(kwds.items())) if self._typed else (args, frozenset(kwds.items()))
        now = self._timer()
        with self.lock:
            expire_time = self.expire_times.get(key)
            if expire_time is not None and now < expire_time:
                return self.cache[key]

            result = self._user_function(*args, **kwds)
            if self._maxsize > 0:
                if key in self.cache:
                    self.cache[key] = result
                    self.expire_times[key] = now + self._ttl
                elif len(self.cache) < self._maxsize:
                    self.cache[key] = result
                    self.expire_times[key] = now + self._ttl
                else:
                    oldest_key = self._find_oldest_key(self.expire_times)
                    del self.cache[oldest_key]
                    del self.expire_times[oldest_key]
                    self.cache[key] = result
                    self.expire_times[key] = now + self._ttl

            return result

    def _find_oldest_key(self, expire_times):
        oldest_key, oldest_time = None, None
        for key, time in expire_times.items():
            if oldest_time is None or time < oldest_time:
                oldest_key = key
                oldest_time = time

        return oldest_key

    def __get__(self, instance, owner):
        if instance is None:
            return self

        def bound_method(*args, **kwds):
            return self.__call__(instance, *args, **kwds)

        bound_method.__name__ = self.__name__
        bound_method.__doc__ = self.__doc__
        bound_method.__module__ = self.__module__
        return bound_method

    __name__ = 'ttl_cache_wrapper'
    __doc__ = 'A memoizing callable with a TTL cache.'

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        cache = dict()
        cache_info = {'hits': 0, 'misses': 0, 'maxsize': maxsize, 'currsize': 0}

        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                cache_info['hits'] += 1
                return cache[key]
            else:
                cache_info['misses'] += 1
                result = func(*args, **kwargs)
                if 'maxsize' not in cache or cache_info['currsize'] < maxsize:
                    cache[key] = result
                    cache_info['currsize'] += 1
                return result

        def cache_clear():
            nonlocal cache, cache_info
            cache.clear()
            cache_info['currsize'] = 0
            cache_info['hits'] = 0
            cache_info['misses'] = 0

        def cache_info():
            return cache_info.copy()

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info

        return wrapper

    return decorator

from collections import OrderedDict
from functools import wraps

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        func.cache_info = _LFUCacheInfo(maxsize=maxsize, hits=0, misses=0, currsize=0, full=False, maxtyped=1 if typed else 0)
        func.cache = OrderedDict()
        func.history = OrderedDict()
        func.access_count = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args if not typed else (func.__module__, func.__name__, args, tuple(kwargs.items()))
            func.cache_info.misses += 1
            if key in func.cache:
                func.access_count[key] += 1
            elif key not in func.history:
                func.cache[key] = func(*args, **kwargs)
                func.access_count[key] = 1
                func.cache_info.currsize += 1
                func.history[key] = func.cache[key]
                if func.cache_info.currsize > func.cache_info.maxsize:
                    oldest_key = next(iter(func.cache))
                    func.cache.pop(oldest_key)
                    func.history.pop(oldest_key)
            else:
                while key in func.history and func.history[key] not in func.cache:
                    oldest_key = next(iter(func.cache))
                    func.cache.pop(oldest_key)
                    func.history.pop(oldest_key)
                func.cache[key] = func.cache[func.history[key]]
                func.access_count[key] = 1

            return func.cache[key]
        return wrapper
    return decorator

class _LFUCacheInfo:
    def __init__(self, maxsize, hits, misses, currsize, full, maxtyped):
        self.maxsize = maxsize
        self.hits = hits
        self.misses = misses
        self.currsize = currsize
        self.full = full
        self.maxtyped = maxtyped

    def __repr__(self):
        return f"LFUCacheInfo(hits={self.hits}, misses={self.misses}, currsize={self.currsize}, maxsize={self.maxsize}, full={self.full}, maxtyped={self.maxtyped})"

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""

    if not self:
        raise KeyError('popitem(): dictionary is empty')

    key = next(iter(self))
    value = self[key]
    del self[key]
    return (key, value)

