@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """

    if not isinstance(e, Exception):
        raise ValueError("The first argument must be an exception instance.")

    if not isinstance(max_level, int) or max_level < 0:
        raise ValueError("The second argument (max_level) must be a non-negative integer.")

    if not isinstance(max_path_level, int) or max_path_level < 0:
        raise ValueError("The third argument (max_path_level) must be a non-negative integer.")

    def format_exception_stack(stack, level):
        if level <= 0:
            return []
        return stack[:level]

    def format_exception_path(path, level):
        if level <= 0:
            return []
        return path[:level]

    def extract_exception_info(e):
        return str(e), e.__class__.__name__, format_exception_stack(e.__traceback__.tb_frame.f_back.f_back.f_locals.items(), max_level), format_exception_path(e.__traceback__.tb_frame.f_back.f_back.f_back.f_locals.items(), max_path_level)

    return ", ".join(extract_exception_info(e))
