def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    from loc import FillRequest, Source, FillRequestSeq

    def contains_fill_request(element):
        if isinstance(element, FillRequest):
            return True
        if isinstance(element, list):
            return any(contains_fill_request(e) for e in element)
        return False

    if isinstance(seq, FillRequest):
        return True
    if isinstance(seq, Source):
        return False
    if isinstance(seq, list):
        return contains_fill_request(seq)

    return False
