        raise ValueError("Unsupported style. Choose from 'html', 'xml', or 'json'")

    rendered_pieces = []
    for piece in pieces:
        if style == 'html':
            rendered_pieces.append(f"<div>{piece}</div>")
        elif style == 'xml':
