import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        commands = [commands]

    for command in commands:
        try:
            if verbose:
                print(f"Running command: {command} with args: {args}")

            if hide_stderr:
                result = subprocess.run([command] + args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, env=env, check=True)
            else:
                result = subprocess.run([command] + args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env=env, check=True)

            if verbose:
                print(result.stdout.decode().strip())

            return result.stdout.decode().strip()

        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Command failed: {e.command} with output: {e.output.decode().strip()}")
            return e.output.decode().strip()

        except Exception as e:
            if verbose:
                print(f"An error occurred: {e}")
            raise e
