import logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. 
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration, 
    and sequence of logging.LogRecord instances containing any parse errors.'''

    if overrides is None:
        overrides = {}

    config_dict = {}
    logging_records = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                config_content = file.read()
                parsed_config = parse_config(config_content, resolve_env, overrides)  # Assuming parse_config function exists
                config_dict[config_filename] = parsed_config
        except Exception as e:
            logger = logging.getLogger(__name__)
            logger.error(f"Error parsing configuration file {config_filename}: {e}")
            error_record = logging.LogRecord(name=__name__, level=logging.ERROR, pathname=config_filename, lineno=0, msg=str(e), args=(), exc_info=None)
            logging_records.append(error_record)

    return config_dict, logging_records
