def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """

    if seq is None:
        raise ValueError("Input sequence cannot be None")

    if not isinstance(seq, (list, tuple, str)):
        raise ValueError("Input sequence must be a list, tuple, or string")

    if bufsize is not None and not isinstance(bufsize, int):
        raise ValueError("bufsize must be an integer")

    if bufsize is not None and bufsize < 0:
        raise ValueError("bufsize must be non-negative")

    if isinstance(seq, (list, tuple)):
        seq = list(seq)

    return seq, type(seq)

