def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    flatten_dict = {}

    if not os.path.exists(plugin_dir):
        raise FileNotFoundError(f"The directory {plugin_dir} does not exist.")

    for root, _, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    spec = json.load(f)

                for key, value in spec.items():
                    if isinstance(value, dict):
                        for subkey, subvalue in flatten_dict.get(key, {}).items():
                            flatten_dict[f"{key}_{subkey}"] = subvalue
                        flatten_dict[key] = {**flatten_dict.get(key, {}), **value}
                    else:
                        flatten_dict[key] = value

    return flatten_dict

